const body = msg.payload;

// Build a Label Studio task from the feedback payload.
// OpenWebUI sends: rating (1=up, -1=down), message, response, comment.
const task = [{
  context:  body.context  || '',
  question: body.message  || '',
  answer:   body.response || '',
  rating:   body.rating,
  comment:  body.comment  || '',
  source:   'user_feedback',
  timestamp: new Date().toISOString()
}];

// Skip thumbs-up with no correction — positive signal but no annotation needed.
if (body.rating === 1 && !body.comment) {
  msg.skip = true;
  msg.payload = { status: 'ok', action: 'skipped' };
  return [null, msg];  // output 2: ack without queuing
}

msg.task     = task;
msg.filename = 'feedback_' + Date.now() + '.json';
msg.payload  = { status: 'ok', action: 'queued' };
return [msg, null];  // output 1: queue for upload

const fs = global.get('fs') || require('fs');
const path = '/tmp/' + msg.filename;
fs.writeFileSync(path, JSON.stringify(msg.task, null, 2));
msg.tmpPath = path;
return msg;
